// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.workerimport android.app.PendingIntentimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport android.os.Buildimport com.google.android.gms.location.Geofenceimport com.google.android.gms.location.GeofencingEventimport com.roshan.persona.automation.scheduler.AutomationSchedulerimport dagger.hilt.EntryPointimport dagger.hilt.InstallInimport dagger.hilt.android.EntryPointAccessorsimport dagger.hilt.components.SingletonComponentimport timber.log.Timber/** * NOUS — Geofence Transition Receiver (Module 8). * * REAL [BroadcastReceiver] that receives geofence transition events from * Google Play Services Location. * * ## How it gets registered * * When [com.roshan.persona.automation.scheduler.AutomationScheduler.scheduleLocationTrigger] * adds a geofence via `GeofencingClient.addGeofences(...)`, it passes a * `PendingIntent` that targets this receiver. When the device crosses the * geofence boundary, Play Services fires the PendingIntent, which delivers * an `Intent` with `ACTION_GEOFENCE_TRIGGERED` to this receiver. * * ## What the receiver does * *   1. Extract the [GeofencingEvent] from the intent. *   2. For each triggering geofence: *      a. Get the request ID (which is the rule ID). *      b. Enqueue a `OneTimeWorkRequest` for [AutomationWorker] via *         [AutomationScheduler.enqueueOneShotFire]. * * The receiver must be registered in the AndroidManifest (so it can be * launched by Play Services even when the app is not running). * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2 Automation</a> */class AutomationGeofenceReceiver : BroadcastReceiver() {    companion object {        /** Intent action fired by the GeofencingClient PendingIntent. */        const val ACTION_GEOFENCE_TRIGGERED = "com.roshan.persona.automation.GEOFENCE_TRIGGERED"        private const val TAG = "GeofenceReceiver"    }    override fun onReceive(context: Context, intent: Intent) {        if (intent.action != ACTION_GEOFENCE_TRIGGERED) {            Timber.tag(TAG).w("Unexpected action: ${intent.action} — ignoring.")            return        }        val event = GeofencingEvent.fromIntent(intent)        if (event == null) {            Timber.tag(TAG).w("No GeofencingEvent in intent — ignoring.")            return        }        if (event.hasError()) {            Timber.tag(TAG).w(                "Geofence error: %d (%s)",                event.errorCode,                com.google.android.gms.location.GeofenceStatusCodes.getStatusCodeString(event.errorCode),            )            return        }        val transition = event.geofenceTransition        val transitionLabel = when (transition) {            Geofence.GEOFENCE_TRANSITION_ENTER -> "ENTER"            Geofence.GEOFENCE_TRANSITION_EXIT -> "EXIT"            Geofence.GEOFENCE_TRANSITION_DWELL -> "DWELL"            else -> "UNKNOWN($transition)"        }        val triggeringGeofences = event.triggeringGeofences        Timber.tag(TAG).i(            "Geofence transition %s — %d geofence(s) triggered.",            transitionLabel, triggeringGeofences?.size ?: 0,        )        val scheduler = EntryPointAccessors.fromApplication(            context.applicationContext,            GeofenceReceiverEntryPoint::class.java,        ).scheduler()        for (geofence in triggeringGeofences.orEmpty()) {            val ruleId = geofence.requestId            Timber.tag(TAG).i("Geofence triggered for rule %s (transition=%s)", ruleId, transitionLabel)            scheduler.enqueueOneShotFire(ruleId, AutomationWorker.TRIGGER_KIND_EVENT)        }    }}/** * Hilt entry point for accessing [AutomationScheduler] from the receiver. */@EntryPoint@InstallIn(SingletonComponent::class)interface GeofenceReceiverEntryPoint {    /** Access the singleton [AutomationScheduler]. */    fun scheduler(): AutomationScheduler}/** * Build a `PendingIntent` that targets [AutomationGeofenceReceiver] for the * given rule ID. Used by [AutomationScheduler] when adding geofences. * * (This is here, not in the scheduler, to keep the receiver + its intent * factory co-located.) */@Suppress("unused")internal fun buildGeofencePendingIntent(context: Context, requestCode: Int): PendingIntent {    val intent = Intent(context, AutomationGeofenceReceiver::class.java).apply {        action = AutomationGeofenceReceiver.ACTION_GEOFENCE_TRIGGERED    }    return PendingIntent.getBroadcast(        context,        requestCode,        intent,        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE        } else {            PendingIntent.FLAG_UPDATE_CURRENT        },    )}